import os,re,numpy as np,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
# Full hypothesis: bg = most common color. Canvas = max bbox dims across colors. Each color's points translated so its bbox top-left goes to (0,0). Overlapping cells: larger-bbox-area color wins. Verify all demos.
from collections import Counter
def f(inp):
    i=np.array(inp); cnt=Counter(i.flatten()); bg=cnt.most_common(1)[0][0]
    pts={v:[tuple(p) for p in np.argwhere(i==v)] for v in set(i.flatten())-{bg}}
    H=max(max(p[0] for p in ps)-min(p[0] for p in ps)+1 for ps in pts.values())
    W=max(max(p[1] for p in ps)-min(p[1] for p in ps)+1 for ps in pts.values())
    order=sorted(pts.items(), key=lambda kv: (max(p[0] for p in kv[1])-min(p[0] for p in kv[1]))*(max(p[1] for p in kv[1])-min(p[1] for p in kv[1])), reverse=True)
    out=np.full((H,W),bg)
    for v,ps in order:
        r0=min(p[0] for p in ps); c0=min(p[1] for p in ps)
        for r,c in ps: out[r-r0,c-c0]=v
    return out.tolist()
ok=all(f(G[k+' input'])==G[k+' output'] for k in ['Demo pair %d'%n for n in range(1,7)])
print('all demos match:', ok)
for k in ['Demo pair %d'%n for n in range(1,7)]:
    print(k, f(G[k+' input'])==G[k+' output'])

